from pathlib import Path

main = Path('src/main.tsx')
main.write_text('''import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React from 'react';
import ReactDOM from 'react-dom/client';
import { ThemeProvider, type Theme } from '@gravity-ui/uikit';

import { App } from './App';

export type { Theme };

ReactDOM.createRoot(document.getElementById('root')"'!).render(
  <React.StrictMode>
    <ThemeProvider theme="system">
      <App />
    </ThemeProvider>
  </React.StrictMode>,
);
'"''')

app = Path('src/App.tsx')
app.write_text('''import { ThemeToggle } from './ThemeToggle';

export function App() {
  return (
    <main style={{ display: 'grid', gap: 24, padding: 24 }}>
      <ThemeToggle />
    </main>
  );
}
''')

toggle = Path('src/ThemeToggle.tsx')
toggle.write_text('''import { SegmentedRadioGroup, useTheme, type Theme } from '@gravity-ui/uikit';

const themeOptions = [
  { value: 'light', content: 'Светлая' },
  { value: 'dark', content: 'Тёмная' },
  { value: 'system', content: 'Системная' },
] as const;

export function ThemeToggle() {
  const theme = useTheme();

  return (
    <SegmentedRadioGroup
      name=\"theme\"
      value={theme}
      onUpdate={(nextTheme) => setTheme(nextTheme as Theme)}
      aria-label=\"Тема оформления\"
    >
      {themeOptions.map(({ value, content }) => (
        <SegmentedRadioGroup.Option key={value} value={value} content={content} />
      ))}
    </SegmentedRadioGroup>
  );
}
''')
PY
npm run build"

